namespace Validly.SourceGenerator.Dtos;

/// <summary>
/// The nearest validatable ancestor of a validatable object
/// </summary>
internal record BaseObjectProperties
{
	/// <summary>
	/// The ancestor is declared in the compilation being generated; its validation is generated by this generator too
	/// </summary>
	public required bool IsFromSource { get; init; }

	/// <summary>
	/// Model of the ancestor; set for ancestors from source, so the generator can resolve its shape
	/// </summary>
	public required ObjectProperties? Object { get; init; }

	/// <summary>
	/// The ancestor has the generated core validation method (<see cref="Consts.ValidateCoreMethodName"/>).
	/// False for ancestors generated by an older version of Validly; those are validated through their ValidateAsync.
	/// </summary>
	public required bool HasCoreMethod { get; init; }

	/// <summary>
	/// The public validation methods of the (metadata) ancestor require IServiceProvider
	/// </summary>
	public required bool RequiresServiceProvider { get; init; }

	/// <summary>
	/// The validation of the (metadata) ancestor is asynchronous
	/// </summary>
	public required bool IsAsync { get; init; }
}
